<script lang="ts">
import { onMount } from 'svelte';
type Drawer='roadmap'|'status'|null; type Repo={repository:string;branch:string;head:string;localMain:string;remoteMain:string;worktree:string;lastCommit:string}; type WP={id:string;title:string;source:string;fields:Record<string,string>;sections:Record<string,string>};
let leftWidth=320,rightWidth=320,drawer:Drawer=null,roadmapText='',roadmapError='',wpError='',repositoryError='',selectedId='AICC-CODEX-ONLY-MIGRATION-001',selected:WP|null=null,repo:Repo|null=null,auth:any={status:'UNAUTHORIZED',record:null},authError='',syncError='',syncStatus='',refreshing=false,lastRefresh='尚未刷新';
$: lines=roadmapText.split('\n'); $: milestone=lines.find(x=>x.startsWith('`M'))?.replaceAll('`','')??'M2 — Authority And Workspace Control'; $: workPackages=lines.filter(x=>x.startsWith('`AICC-')).map(x=>x.replaceAll('`','').replace(',','').trim()).filter((x,i,a)=>a.indexOf(x)===i);
async function get<T>(url:string):Promise<T>{const r=await fetch(url);const d=await r.json();if(!r.ok)throw new Error(d.error);return d;}
async function loadRoadmap(){try{roadmapText=(await get<{content:string}>('/api/roadmap')).content;roadmapError='';}catch(e){roadmapError=e instanceof Error?e.message:'ROADMAP_ERROR';}}
async function loadWP(id=selectedId){selectedId=id;try{selected=await get<WP>(`/api/work-packages/${encodeURIComponent(id)}`);wpError='';auth=await get(`/api/authorization?workPackageId=${encodeURIComponent(selectedId)}`);}catch(e){selected=null;wpError=e instanceof Error?e.message:'WP_ERROR';}}
async function loadRepo(){try{repo=await get<Repo>('/api/repository');repositoryError='';auth=await get(`/api/authorization?workPackageId=${encodeURIComponent(selectedId)}`);}catch(e){repo=null;repositoryError=e instanceof Error?e.message:'REPOSITORY_ERROR';}}
async function refresh(){refreshing=true;await Promise.allSettled([loadRoadmap(),loadRepo(),loadWP()]);lastRefresh=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});refreshing=false;}
async function authorize(){authError='';try{const r=await fetch('/api/authorization',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({workPackageId:selectedId,confirmed:true})});const d=await r.json();if(!r.ok)throw new Error(d.error);auth=d;}catch(e){authError=e instanceof Error?e.message:'AUTHORIZATION_ERROR';}}
async function syncMain(){syncError='';try{const r=await fetch('/api/repository/sync-main',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const d=await r.json();if(!r.ok)throw new Error(d.error);syncStatus=d.status;await refresh();}catch(e){syncError=e instanceof Error?e.message:'SYNC_ERROR';}}
function resize(side:'left'|'right',ev:PointerEvent){const x=ev.clientX,start=side==='left'?leftWidth:rightWidth;const move=(e:PointerEvent)=>{const n=Math.max(side==='left'?240:260,Math.min(420,start+(side==='left'?e.clientX-x:x-e.clientX)));if(side==='left')leftWidth=n;else rightWidth=n;};const up=()=>{removeEventListener('pointermove',move);removeEventListener('pointerup',up);localStorage.setItem(`aicc-v2-${side}-width`,String(side==='left'?leftWidth:rightWidth));};addEventListener('pointermove',move);addEventListener('pointerup',up)}
onMount(()=>{leftWidth=Number(localStorage.getItem('aicc-v2-left-width'))||320;rightWidth=Number(localStorage.getItem('aicc-v2-right-width'))||320;void refresh();});
</script>
<svelte:head><title>AICC V2 · Control Center</title><meta name="viewport" content="width=device-width, initial-scale=1" /></svelte:head>
<div class="app-shell"><header class="global-header"><div class="brand"><div class="brand-icon">A</div><div><strong>AI Control Center</strong><span>V2 · Local Web First</span></div></div><div class="header-context"><span class="status-dot"></span><span>本地工作区</span><span class="mono">AIcontrolcenter</span></div><div class="header-actions"><button class="mobile-trigger" onclick={()=>drawer=drawer==='roadmap'?null:'roadmap'}>☰</button><span class="branch-badge">{repo?.branch??'rebuild/aicc-v2'}</span><button class="mobile-trigger" onclick={()=>drawer=drawer==='status'?null:'status'}>◌</button></div></header>
<div class="workspace" style={`--left-width:${leftWidth}px;--right-width:${rightWidth}px`}>
<aside class:drawer-open={drawer==='roadmap'} class="roadmap panel"><div class="panel-header"><div><span class="kicker">01 / ROADMAP</span><h2>项目路线图</h2></div></div><div class="roadmap-source"><span class="live-dot"></span><span>唯一展示来源</span><code>01_LIVING_ROADMAP.md</code></div>{#if roadmapError}<div class="source-error">路线图读取失败<code>{roadmapError}</code></div>{:else}<div class="roadmap-content"><div class="milestone"><span class="milestone-marker">M2</span><div><strong>{milestone}</strong><small>当前里程碑</small></div></div><div class="tree-line"></div>{#each workPackages.slice(0,7) as item,i}<button class:current={item===selectedId} class="roadmap-item" onclick={()=>loadWP(item)}><span class="item-marker">{item===selectedId?'●':i<3?'✓':'○'}</span><span><strong>{item}</strong><small>{item===selectedId?'当前工作包 · 进行中':i<3?'已完成':'计划中'}</small></span></button>{/each}</div>{/if}</aside><div class="resize-handle" onpointerdown={(e)=>resize('left',e)} role="separator" aria-label="调整路线图宽度"></div>
<main class="center panel"><div class="center-inner"><section class="hero"><span class="kicker">CONTROL CENTER / MVP-003</span><h1>保持清醒，<em>掌控变更。</em></h1><p>本地优先的 Codex 控制中心。所有执行能力在 Owner 授权后开放。</p></section><section class="action-zone"><div class="section-label"><span>Owner Action Zone</span><small>显式 Owner 操作</small></div><div class="actions"><button class="action primary" onclick={refresh} disabled={refreshing}>{refreshing?'刷新中…':'刷新状态'}</button><button class="action" onclick={authorize} disabled={!repo||!!selected===false||auth.status==='AUTHORIZED'}>确认授权 <small>{auth.status==='AUTHORIZED'?'已授权':authError||'READY'}</small></button><button class="action" onclick={syncMain} disabled={!repo||repo.worktree!=='CLEAN'||repo.branch==='main'}>同步本地 main <small>{syncStatus||syncError||'SAFE FF'}</small></button>{#each ['启动 Codex','重试','停止'] as action}<button class="action disabled" disabled>{action}<small>NOT_IMPLEMENTED</small></button>{/each}</div></section><section class="overview"><div class="section-label"><span>Work Package detail</span><small>Read-only source</small></div>{#if wpError}<div class="detail-error"><strong>工作包读取失败</strong><code>{wpError}</code><p>Roadmap remains available.</p></div>{:else if selected}<article class="detail-card"><div class="detail-top"><span class="tag">{selected.id}</span><span class="truth">READ ONLY</span></div><h3>{selected.title}</h3><p class="source-path">{selected.source}</p><div class="detail-grid"><div><b>Goal / Scope</b><p>{selected.sections['Goal']??selected.sections['目标']??'未提供'}</p></div><div><b>Status</b><p>{selected.fields['Status']??selected.fields['状态']??'未提供'}</p></div><div><b>Dependencies</b><p>{selected.sections['Dependencies']??'未提供'}</p></div><div><b>Acceptance Criteria</b><p>{selected.sections['Acceptance Criteria']??'未提供'}</p></div></div></article>{:else}<div class="detail-error">工作包读取中…</div>{/if}</section><section class="principles"><div class="section-label"><span>V2 operating principles</span><small>Last refresh {lastRefresh}</small></div><div class="principle-grid"><div><b>LOCAL FIRST</b><p>状态从当前工作区读取</p></div><div><b>CODEX ONLY</b><p>未实现能力明确标记</p></div><div><b>TRUTHFUL</b><p>来源错误独立显示</p></div></div></section></div></main><div class="resize-handle" onpointerdown={(e)=>resize('right',e)} role="separator" aria-label="调整状态宽度"></div>
<aside class:drawer-open={drawer==='status'} class="status panel"><div class="panel-header"><div><span class="kicker">03 / EVIDENCE</span><h2>状态与证据</h2></div></div>{#if repositoryError}<div class="source-error">Repository 读取失败<code>{repositoryError}</code></div>{:else}<div class="evidence-intro"><span class="live-dot"></span><strong>真实本地证据</strong><small>{lastRefresh}</small></div><div class="evidence-list">{#each [['Repository',repo?.repository],['Current Branch',repo?.branch],['Current HEAD',repo?.head],['Local Main',repo?.localMain],['Remote Main',repo?.remoteMain],['Worktree',repo?.worktree],['Last Commit',repo?.lastCommit]] as row}<div><span>{row[0]}</span><code class:truth={row[0]==='Worktree'}>{row[1]??'读取中…'}</code></div>{/each}</div>{/if}<div class="auth-card"><span class="kicker">OWNER AUTHORIZATION</span><strong>Owner 授权 · {auth.status==='AUTHORIZED'?'已授权':auth.status==='INVALID'?'已失效':'未授权'}</strong>{#if auth.record}<p>Work Package: {auth.record.workPackageId}<br />Branch: {auth.record.branch}<br />Authorized At: {auth.record.authorizedAt}</p>{:else}<p>尚未创建 Owner 授权记录</p>{/if}</div><div class="runtime-list"><div><span>Codex Runtime</span><b>NOT_IMPLEMENTED</b></div><div><span>Writer Lock</span><b>NOT_IMPLEMENTED</b></div></div></aside></div></div>
